from ipaddress import ip_address, ip_network
ip = ip_address('76.172.10.140')
best = None
for m in range(33):
    net = ip_network(f'{ip}/{m}', 0)
    if net.num_addresses > 1 << 16:
        continue
    if sum(1 for x in net if f'{x:b}'.count('1') % 2 == 0) >= 100:
        best = m
print(best)
